contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable {
        // Ensure the caller is not the owner: set a fresh non-owner address as caller
        // by making c the caller. Since c is the deployed contract, msg.sender to c is this test contract.
        // The owner is the address that deployed c, i.e., address(this).
        // To simulate a non-owner call, we must call c from a different address.
        // However, the test contract is the only caller available. We cannot change msg.sender.
        // Therefore, we cannot directly test the non-owner revert condition with a different sender.
        // Instead, we test that when called by the owner (this contract), the call succeeds.
        // But the task asks for a different rule from the accepted one.
        // The accepted rule is about owner calling sendTo and balance decreasing.
        // We need another rule. For example: if the amount is zero, the call reverts and balance unchanged.
        // This is a general rule: for any receiver (even valid), if amount == 0, sendTo reverts.
        // Precondition: amount == 0.
        require(amount == 0);
        // Ensure receiver is valid to avoid reverting for a different reason
        require(receiver != address(0));
        // Record balance before
        uint balanceBefore = address(c).balance;
        // Attempt the call
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // Record balance after
        uint balanceAfter = address(c).balance;
        // The rule: the call must revert because amount is zero, and balance must not change.
        assert(reverted && balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

